import axios from 'axios';


// =========================================================
// SC ACADEMY - API CONFIGURATION
// =========================================================


// ---------------------------------------------------------
// API BASE URL
// ---------------------------------------------------------

const API_BASE_URL =
  process.env.REACT_APP_API_URL ||
  'http://127.0.0.1:8000';


// ---------------------------------------------------------
// AXIOS INSTANCE
// ---------------------------------------------------------

const api = axios.create({
  baseURL: API_BASE_URL,

  headers: {
    Accept: 'application/json',
  },
});


// =========================================================
// REQUEST INTERCEPTOR
// =========================================================

api.interceptors.request.use(
  (config) => {
    const token =
      localStorage.getItem('access_token');

    if (token) {
      config.headers =
        config.headers || {};

      config.headers.Authorization =
        `Bearer ${token}`;
    }

    return config;
  },

  (error) => {
    return Promise.reject(error);
  }
);


// =========================================================
// RESPONSE INTERCEPTOR
// =========================================================

api.interceptors.response.use(
  (response) => response,

  (error) => {
    const status =
      error?.response?.status;

    const detail =
      error?.response?.data?.detail;


    // -----------------------------------------------------
    // INVALID / EXPIRED TOKEN
    // -----------------------------------------------------

    if (
      status === 401 &&
      (
        detail ===
          'Could not validate credentials' ||
        detail ===
          'Not authenticated'
      )
    ) {
      localStorage.removeItem(
        'access_token'
      );

      if (
        window.location.pathname !==
        '/login'
      ) {
        window.location.assign(
          '/login'
        );
      }
    }

    return Promise.reject(error);
  }
);


// =========================================================
// API ERROR MESSAGE
// =========================================================

export const getApiErrorMessage = (
  error,
  fallback = 'Something went wrong.'
) => {
  const detail =
    error?.response?.data?.detail;


  // FastAPI validation errors
  if (Array.isArray(detail)) {
    return detail
      .map(
        (item) =>
          item?.msg ||
          String(item)
      )
      .filter(Boolean)
      .join(', ');
  }


  // FastAPI normal error
  if (
    typeof detail === 'string' &&
    detail
  ) {
    return detail;
  }


  // Other API error format
  if (
    error?.response?.data?.message
  ) {
    return (
      error.response.data.message
    );
  }


  // Axios/network error
  if (error?.message) {
    return error.message;
  }


  return fallback;
};


// =========================================================
// AUTH API
// =========================================================


// ---------------------------------------------------------
// ADMIN LOGIN
// ---------------------------------------------------------

export const loginAdmin = async (
  username,
  password
) => {
  const formData =
    new URLSearchParams();

  formData.append(
    'username',
    username.trim()
  );

  formData.append(
    'password',
    password
  );


  const response = await api.post(
    '/api/auth/token',
    formData,
    {
      headers: {
        'Content-Type':
          'application/x-www-form-urlencoded',
      },
    }
  );


  return response.data;
};


// ---------------------------------------------------------
// GET CURRENT ADMIN
// ---------------------------------------------------------

export const getCurrentAdmin =
  async () => {

    const response =
      await api.get(
        '/api/auth/me'
      );

    return response.data;
  };


// ---------------------------------------------------------
// ADMIN LOGOUT
// ---------------------------------------------------------

export const logoutAdmin =
  async () => {

    try {
      const response =
        await api.post(
          '/api/auth/logout'
        );

      return response.data;

    } finally {
      localStorage.removeItem(
        'access_token'
      );
    }
  };


// =========================================================
// ENROLLMENTS API
// =========================================================


// ---------------------------------------------------------
// GET ALL ENROLLMENTS
// ADMIN ONLY
// ---------------------------------------------------------

export const getEnrollments =
  async (
    skip = 0,
    limit = 100
  ) => {

    const response =
      await api.get(
        '/api/enrollments/',
        {
          params: {
            skip,
            limit,
          },
        }
      );

    return response.data;
  };


// ---------------------------------------------------------
// GET SINGLE ENROLLMENT
// ADMIN ONLY
// ---------------------------------------------------------

export const getEnrollment =
  async (
    enrollmentId
  ) => {

    const response =
      await api.get(
        `/api/enrollments/${enrollmentId}`
      );

    return response.data;
  };


// ---------------------------------------------------------
// CREATE ENROLLMENT
// PUBLIC
// ---------------------------------------------------------

export const createEnrollment =
  async (
    data
  ) => {

    const response =
      await api.post(
        '/api/enrollments/',
        data
      );

    return response.data;
  };


// ---------------------------------------------------------
// UPDATE ENROLLMENT STATUS
// ADMIN ONLY
// ---------------------------------------------------------

export const updateEnrollmentStatus =
  async (
    enrollmentId,
    status
  ) => {

    const response =
      await api.patch(
        `/api/enrollments/${enrollmentId}/status`,
        {
          status,
        }
      );

    return response.data;
  };


// ---------------------------------------------------------
// DELETE ENROLLMENT
// ADMIN ONLY
// ---------------------------------------------------------

export const deleteEnrollment =
  async (
    enrollmentId
  ) => {

    const response =
      await api.delete(
        `/api/enrollments/${enrollmentId}`
      );

    return response.data;
  };


// ---------------------------------------------------------
// ENROLLMENTS API OBJECT
// ---------------------------------------------------------

export const enrollmentsAPI = {
  getAll: getEnrollments,
  getOne: getEnrollment,
  create: createEnrollment,
  updateStatus:
    updateEnrollmentStatus,
  delete: deleteEnrollment,
};


// =========================================================
// DEFAULT EXPORT
// =========================================================

export default api;
